INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('492effee-6adc-4b31-91c4-fa806581931e','api_510_pressure_vessel_external','API 510 Pressure Vessel External Inspection','1','Pressure vessel inspection','global','60','180000','cci_advanced'::public.cci_credential_tier,'External in-service inspection of an ASME Section VIII pressure vessel per API 510 §6. Covers nameplate verification, external visual condition, insulation / CUI examination, support and foundation condition, relief device verification, and external UT thickness readings on accessible courses.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('f264ae5c-e8cc-4c00-a724-2a5115137458','api_570_piping_external','API 570 Process Piping External Inspection','1','Process piping inspection','global','60','220000','cci_advanced'::public.cci_credential_tier,'External inspection of in-service process piping circuits per API 570 §6 / §7. Includes walkdown against the ISO drawing, support condition, coating and insulation condition, TML thickness readings at established CMLs, and review of any in-service damage indications (leaks, staining, vibration).','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('26737b22-2eec-4a0f-94a1-eba3bdb8ccb9','api_653_external_tank_inspection','API 653 External AST Inspection','1','Above-ground storage tank inspection','global','60','450000','cci_advanced'::public.cci_credential_tier,'External (out-of-service or in-service) inspection of an above-ground welded steel storage tank per API 653 §6. Includes shell UT thickness mapping, bottom-edge settlement survey, roof condition assessment, foundation/anchor-bolt walk, and cathodic-protection readings. Authorised inspector must hold a current API 653 certification.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('58ede940-4c50-4206-aa93-6051f3632d8f','api_686_machinery_installation_inspection','Machinery Installation Inspection (API 686)','1','Machinery installation','global','12','320000','cci_advanced'::public.cci_credential_tier,'End-to-end installation audit of refinery / petrochemical rotating equipment per API 686 (Recommended Practice for Machinery Installation and Installation Design). Covers foundation acceptance, baseplate flatness and grout integrity, soft-foot, piping strain, anchor-bolt pre-load, coupling spacing, lube-oil flushing, and final cold-alignment acceptance. Output supports mechanical completion sign-off.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('33ece5fc-50f1-46b9-b3e1-515b3b23260b','arc_flash_hazard_analysis','Arc-Flash Hazard Analysis (IEEE 1584 / NFPA 70E)','1','Arc-flash hazard analysis','global','60','850000','cci_lead'::public.cci_credential_tier,'Engineered arc-flash hazard analysis per IEEE 1584-2018 and NFPA 70E-2024. Builds the system one-line, runs the short-circuit and arc-flash incident-energy calculation, produces incident-energy / PPE category labels for each piece of equipment, and issues mitigation recommendations. NFPA 70E §130.5 mandates a 5-year update interval. PE stamp on the analysis report is required for equipment over 50 V where the AHJ requires it.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('39c4b219-1af3-4ff5-9a45-e7dc26cfd684','asphalt_paving_qc','Asphalt Paving QC (Superpave / AASHTO M323)','1','Asphalt QC','global','12','70000','cci_basic'::public.cci_credential_tier,'Quality-control monitoring of hot-mix asphalt placement per the Superpave methodology (AASHTO M323 / M332). Covers mix temperature at delivery, mat density via cores or nuclear gauge, joint construction, and adherence to the approved JMF (job-mix formula).','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('28e4401c-0290-4532-923d-e2c755256b14','batch_records_gmp_audit_specialty_chemical','Batch Records & GMP Audit (FDA 21 CFR Part 211)','1','GMP / Batch Records','global','12','320000','cci_advanced'::public.cci_credential_tier,'Audit of completed manufacturing batch records, deviation reports, and CAPA closure against US FDA 21 CFR Part 211 (cGMP for finished pharmaceuticals) or the relevant ICH Q7 chapters for active pharmaceutical ingredients. Suitable for specialty-chemical and pharmaceutical-intermediate sites under FDA inspection.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('9bdb809c-3170-4c49-a4c7-5f0b87186ff1','bolt_torque_pressure_boundary_asme_pcc1','Bolted Joint Assembly Inspection (ASME PCC-1)','1','Bolted joint assembly','global','12','70000','cci_basic'::public.cci_credential_tier,'Inspection of bolted flanged-joint assembly on pressure-boundary joints per ASME PCC-1 (Guidelines for Pressure Boundary Bolted Flange Joint Assembly). Confirms flange-face condition, gasket material and orientation, bolt and nut compatibility, lubrication, assembly pattern (star/cross), and final target-torque or bolt-tensioning verification. Joint Integrity Technician qualification per PCC-1 Appendix A is preferred.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('197b2619-f2c8-491f-8d4c-fda02f8ff8db','bridge_routine_inspection_nbis','Routine Bridge Inspection (FHWA NBIS / AASHTO MBE)','1','Bridge inspection','global','24','350000','cci_advanced'::public.cci_credential_tier,'Routine 24-month bridge inspection per the FHWA National Bridge Inspection Standards (NBIS, 23 CFR 650 Subpart C) and AASHTO Manual for Bridge Evaluation. Records element-level condition ratings, scour/foundation condition, deck/superstructure/substructure condition, and load-rating notes. Inspector must be a Team Leader meeting NBIS qualifications.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('91a2fa65-4589-4e5c-a7e4-4467158da198','catalyst_loading_unloading_qc','Catalyst Loading / Unloading QC','1','Catalyst Handling','global','12','260000','cci_advanced'::public.cci_credential_tier,'QC oversight of a catalyst loading or unloading campaign on a reactor (FCC, hydrotreater, reformer, hydrocracker, fixed-bed). Verifies inert-atmosphere monitoring, breathing-air supply, drum / bulk-bag chain-of-custody from the supplier, sock-loading or dense-packing technique, layer-by-layer level surveys, and post-load nitrogen-blanketed close-out. Performed by an inspector working under the catalyst-vendor procedure.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('4ae97436-0dab-4716-830d-3f0a2fdd2d6e','circuit_breaker_primary_injection_testing','Circuit Breaker Primary Current Injection Testing','1','Protective device testing','global','12','150000','cci_advanced'::public.cci_credential_tier,'Primary current injection testing of LV/MV power circuit breakers per NETA MTS §7.6. Confirms long-time, short-time, instantaneous, and (where applicable) ground-fault trip behaviour against the protective-device-coordination study. Records as-found and as-left trip-unit settings for the asset record.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('1d986894-f662-400e-b7a4-f09385525ce8','concrete_compressive_strength_acceptance','Concrete Compressive Strength Acceptance (ACI 318 / ASTM C39)','1','Concrete acceptance testing','global','12','40000','cci_basic'::public.cci_credential_tier,'Witness and document concrete cylinder/cube compressive-strength testing per ASTM C39 against the mix-design acceptance criteria in ACI 318 §26.12. Includes sample identification, break-machine operation, fresh-concrete properties at sampling (slump, air, temperature), and break-result acceptance.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('a8d0d6ff-912b-4994-be09-863b5ba78542','concrete_pre_pour_inspection','Concrete Pre-Pour Inspection (Rebar + Formwork)','1','Pre-pour inspection','global','12','120000','cci_advanced'::public.cci_credential_tier,'Pre-pour inspection of reinforcement, embedded items, and formwork per ACI 318 §26.6 and §26.11. Confirms rebar size, spacing, lap length, clear cover, and tie pattern against the structural drawing; checks formwork bracing, line/grade, and embed/anchor placement before the pour is released.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('f179f15c-bec4-4a8a-8c05-d4fc37bbfdba','crane_annual_structural_inspection_asme_b30','Crane Annual Structural + Functional Inspection (ASME B30 / OSHA 1910.179)','1','Crane inspection','global','12','200000','cci_advanced'::public.cci_credential_tier,'Annual periodic inspection of overhead, mobile, or articulating cranes per the applicable ASME B30 volume (B30.2 / B30.5 / B30.22 as relevant) and OSHA 1910.179 / 1926.1412. Covers structural members, welds, hooks (NDE per ASME B30.10), wire rope and rigging, brakes, limit switches, controls, and load test if required. Inspector must be a Qualified Person per the applicable B30 definition.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('612afcbe-395d-4360-b60a-9abed524dfb3','cwi_visual_weld_inspection','AWS D1.1 Visual Weld Inspection (CWI)','1','Welding inspection','global','12','85000','cci_basic'::public.cci_credential_tier,'Visual examination of structural and pressure welding per AWS D1.1 / D1.5 by a Certified Welding Inspector. Pre-, in-process, and post-weld visual acceptance with WPS / PQR verification. Suitable for construction punch-list weld sign-off and turnaround weld witness.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('8d49bc75-d977-4f4c-a0bc-88f9cc291e3b','distillation_column_internals_inspection','Distillation Column Internals Inspection (Trays + Packing)','1','Distillation Column Internals','global','60','350000','cci_advanced'::public.cci_credential_tier,'Internal inspection of a distillation / fractionation tower during turnaround. Covers tray flatness and bowing, downcomer condition, weir levelness, bubble caps / valves / sieve hole condition, structured / random packing condition, and liquid distributor levelness. Output is a per-tray / per-bed disposition feeding the unit revamp or continued-service decision.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('9045bea7-0e1d-4230-b5e1-8aea8d0f19c8','earthworks_compaction_modified_proctor','Earthworks Compaction (Modified Proctor / ASTM D1557)','1','Earthworks compaction','global','12','50000','cci_basic'::public.cci_credential_tier,'Field density / compaction acceptance testing of structural fill and subgrade against a modified Proctor maximum dry density per ASTM D1557. Includes nuclear density gauge or sand-cone readings, moisture content, and lift-by-lift acceptance vs. project specification.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('c6e2e4b1-41d2-4f72-87aa-d21757cef540','epa_rmp_compliance_audit','EPA Risk Management Program Audit (40 CFR Part 68)','1','EPA Risk Management Program','global','60','900000','cci_lead'::public.cci_credential_tier,'Compliance audit of the site EPA Risk Management Program per 40 CFR Part 68. Determines the applicable program level (1, 2, or 3), reviews the offsite consequence analysis, prevention program, emergency response program, and 5-year accident history. Audits are required every 3 years and at every RMP resubmission. Audit must be conducted by a knowledgeable person not directly responsible for the program.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
