INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('0091cf01-b50a-4eeb-a24d-f7ac14e51480','field_machinery_baseplate_grouting','Field Machinery Baseplate Grouting + Soft-Foot Check (API 686 Ch.4)','1','Baseplate grouting','global','12','110000','cci_basic'::public.cci_credential_tier,'Field inspection of machinery baseplate epoxy or cementitious grouting per API 686 Chapter 4. Covers anchor-bolt isolation, baseplate cleanliness and surface prep, grout-mix proportions and ambient cure conditions, post-cure flatness, and final soft-foot check at each anchor location. Output supports mechanical completion of a new install or rebuild.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('c141b0d4-dff6-4f88-9e46-72bbbf11c7ef','gearbox_borescope_oil_sample_inspection','Gearbox Borescope + Oil Sample Inspection','1','Gearbox condition','global','12','160000','cci_advanced'::public.cci_credential_tier,'Combined condition assessment of an enclosed gearbox: external borescope of gear meshes and bearings, lube-oil sample for laboratory analysis (viscosity, water, ferrous/non-ferrous wear particles via ICP or PQ index, ISO 4406 cleanliness code), and review of vibration / temperature history. Output is a remaining-useful-life recommendation and a re-inspection interval.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('768abb72-26df-4dd7-a426-a7995da61167','grounding_bonding_verification','Grounding & Bonding System Verification (IEEE 81)','1','Grounding & bonding','global','36','70000','cci_basic'::public.cci_credential_tier,'On-site verification of grounding electrode and bonding system effectiveness per IEEE 81-2012 and NEC Article 250. Performs fall-of-potential (3-point) or clamp-on ground resistance testing on each electrode, continuity checks on bonding jumpers, and a system one-line markup with measured values. Recommended retest interval per IEEE 81 §8 is 36 months for facility grounds.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('eab0bba8-af8a-40e9-a2d0-97c65776310e','hazardous_area_classification_audit_iec_60079','Hazardous Area Classification + Ex Equipment Audit (IEC 60079 / NEC 500)','1','Hazardous Area / Ex Equipment','global','36','300000','cci_advanced'::public.cci_credential_tier,'Field audit of installed electrical equipment in classified hazardous areas against the site area-classification drawing per IEC 60079-14 (or NEC Article 500 in the US). Verifies equipment certification (Ex d / e / i / n / m / o / p), nameplate marking, cable-gland integrity, and earthing/bonding. Inspector must hold IECEx CoPC Ex 01-04 or equivalent.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('d987590d-89f3-40be-9bb8-3563d2cc926f','heat_exchanger_turnaround_inspection','Heat Exchanger Turnaround Inspection (Eddy Current + Tubesheet)','1','Heat Exchanger Inspection','global','60','380000','cci_advanced'::public.cci_credential_tier,'Internal turnaround inspection of a shell-and-tube heat exchanger after pull and cleaning. Covers shell-side visual, channel head + tubesheet visual + dimensional, eddy current tube testing (or IRIS where ferrous), and bundle straightness. Output is the per-tube disposition (in-service / plug / re-tube) feeding the unit reliability plan.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('19f20104-8fb8-486b-81ba-0f273c1905eb','heavy_lift_rigging_plan_witness','Heavy / Critical Lift Rigging Plan Witness','1','Critical lift witness','global','12','150000','cci_advanced'::public.cci_credential_tier,'On-site witness of a critical / heavy lift against an engineered lift plan. Confirms the lift plan is current, the crane and rigging match the plan, the centre-of-gravity assumptions are supported, ground-bearing pressure is within crane-mat rating, and the dry-run / tag-line procedure was executed before the live lift. Sign-off feeds the project lift register.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('92865104-f982-47d3-af40-02a03a7d0d51','hydroflushing_chemical_cleaning_acceptance','Hydroflushing / Chemical Cleaning Acceptance','1','Cleaning acceptance','global','12','80000','cci_basic'::public.cci_credential_tier,'Acceptance inspection of new-construction pipe and equipment after hydroflushing, mechanical cleaning, or chemical degreasing. Verifies achieved cleanliness against project specification (typical: 100 μm strainer cleanliness, no rust / mill scale, dry condition), records cleaning medium and disposal evidence, and signs off the system as ready for hydrotest or chemical preservation.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('7f86a418-c3ed-462d-957c-edb6889bfa6a','hydrostatic_pressure_test_piping_asme_b31_3','Hydrostatic Pressure Test — Process Piping (ASME B31.3)','1','Pressure testing','global','12','180000','cci_advanced'::public.cci_credential_tier,'Witness and document a hydrostatic leak/strength test of a process-piping system per ASME B31.3 §345. Confirms test medium and temperature, vent / drain / instrumentation isolation, pre-test calibration of the test gauge, a minimum 10-minute hold at 1.5 × design pressure, walk-down for leaks, and post-test depressurisation and drying. Accepted as the final pressure-integrity acceptance prior to system handover.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('1ba8b243-a47e-4614-9251-2c0c0506cde0','ir_thermography_electrical_survey','Infrared Thermography — Electrical Survey (NETA MTS / NFPA 70B)','1','Predictive maintenance — thermography','global','12','180000','cci_advanced'::public.cci_credential_tier,'Infrared thermographic survey of energised electrical distribution equipment per the NETA MTS guideline and NFPA 70B Chapter 11. Captures thermogram + visible-light pairs of every accessible connection, ranks findings by severity (ΔT above ambient / above similar-component baseline), and recommends corrective actions. Inspector must hold a Level II Infrared Thermographer certification (ITC or ASNT TC-1A).','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('888448c8-db7c-424b-99ca-681f01c68d42','ldar_method_21_quarterly_campaign','LDAR Method 21 Quarterly Campaign (EPA 40 CFR §60.485 / §63.180)','1','LDAR / Fugitive Emissions','global','3','280000','cci_advanced'::public.cci_credential_tier,'Quarterly leak detection and repair (LDAR) survey on the component population (connectors, valves, flanges, pumps) per EPA Method 21. Covers calibration of the analyser at the start of every campaign, screening at each component, first-attempt repair within 5 days, final repair within 15 days, and recordkeeping of all leaks ≥ leak-definition concentration. Optical Gas Imaging (OGI) may be used as the alternative work practice per §60.18.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('29bcc9d8-bcef-44ea-8809-561d09c63645','mechanical_integrity_program_audit','Mechanical Integrity Program Audit (PSM §1910.119(j) / API 580)','1','Mechanical Integrity','global','36','550000','cci_advanced'::public.cci_credential_tier,'Audit of the site Mechanical Integrity program per OSHA PSM Element 8 (1910.119(j)) and API 580/581 RBI principles. Covers equipment criticality classification, inspection planning, frequency justification, deficiency closure, MoC for inspection-procedure changes, training of inspection personnel, and document-control practices.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('3c90ac39-5e41-4179-9781-36593fe0ec6e','motor_circuit_analysis_offline','Motor Circuit Analysis — Off-line (Insulation, PI, Winding R)','1','Rotating machinery electrical testing','global','12','120000','cci_advanced'::public.cci_credential_tier,'Off-line electrical testing of three-phase induction or synchronous motors. Includes insulation-resistance (megger) at multiple voltages (500 V / 1000 V / 5000 V as appropriate), polarisation-index and dielectric-absorption-ratio computation, winding resistance balance, and optional surge-comparison test for inter-turn faults. Suitable for both routine maintenance and post-trip diagnostics.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('b929f08c-b7b7-4403-a2af-bcdc75bc4c73','mt_pt_critical_weld_inspection','Magnetic Particle / Liquid Penetrant — Critical Welds','1','NDT — Surface methods','global','12','70000','cci_basic'::public.cci_credential_tier,'Surface NDT (wet/dry MT or visible/fluorescent PT) of critical welds per ASME BPVC Sec. V Art. 7 (MT) / Art. 6 (PT). Documents pre-test surface prep, indication mapping, and post-test cleanup. Inspector must hold a current ASNT Level II MT and PT certification.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('6314e247-455d-4cc7-a4c2-d29f5c476ff0','mv_switchgear_inspection','Medium-Voltage Switchgear Inspection (5–38 kV)','1','Switchgear inspection','global','12','280000','cci_advanced'::public.cci_credential_tier,'De-energised inspection and electrical testing of medium-voltage (5–38 kV) metal-clad or metal-enclosed switchgear per NETA MTS §7.5. Covers visual condition of bus and primary contacts, insulation resistance (megger) at multiple voltages, contact resistance (ductor) on all primary disconnects, breaker time-travel test, and partial-discharge survey on accessible terminations.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('d4a4c589-a228-4d81-bbf3-c2b32c3411c4','nace_cip_coating_inspection','NACE / AMPP CIP Coating Inspection','1','Coatings inspection','global','12','120000','cci_basic'::public.cci_credential_tier,'Protective-coating system inspection per NACE / AMPP CIP Level 2 — surface preparation acceptance (SSPC visual standards + profile / soluble salts), wet film and dry film thickness, holiday testing, and environmental conditions logging. Required on most new-construction and recoat scopes.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('1a489ed2-e539-4f8d-804b-ebaa5007dd37','neta_ats_acceptance_testing','NETA ATS Acceptance Testing (Newly Installed Equipment)','1','Electrical acceptance testing','global','12','420000','cci_advanced'::public.cci_credential_tier,'Acceptance testing of newly installed electrical power equipment per the InterNational Electrical Testing Association ANSI/NETA ATS specification. Covers insulation resistance, contact resistance, TTR/CT/PT verification, protective-relay calibration, and final functional testing prior to energisation. Inspector must hold a current NETA Level III or IV certification.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
