INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('fe304fe0-583a-4c0e-bc22-ba9cfa403124','pha_hazop_facilitation','PHA / HAZOP Team Facilitation (PSM §1910.119(e))','1','Process Hazard Analysis','global','60','1200000','cci_lead'::public.cci_credential_tier,'Multi-day Process Hazard Analysis using HAZOP, what-if, LOPA, or FMEA methodology, led by a certified facilitator with a multi-disciplinary site team. Output is the signed PHA report, recommendation register, and risk ranking. PSM §1910.119(e)(6) mandates revalidation at least every 5 years.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('e4c93804-21b3-4a33-a258-d25e4b326d68','piping_class_break_audit_b31_3','Piping Class Break + Material Trace Audit (ASME B31.3)','1','Piping Material Trace','global','36','240000','cci_advanced'::public.cci_credential_tier,'Field audit of piping class-break locations and material-of-construction trace on a process unit per ASME B31.3 §M300. Confirms every pipe spool, fitting, and valve matches the piping line list and PMI of any alloy-specific runs. Identifies any class-break mis-locations (e.g. carbon-steel spool installed in an alloy-spec line) and produces an MOC item if found.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('7c891c58-4614-4f9b-8956-75ac11b6953a','piping_construction_visual_inspection','Process Piping Construction Visual Inspection (ASME B31.3 / AWS QC1)','1','Piping construction','global','12','220000','cci_advanced'::public.cci_credential_tier,'Field visual inspection of new-construction process piping per ASME B31.3 §341. Covers material verification against the line list, fit-up and joint preparation, weld visual acceptance per AWS QC1, post-weld heat-treatment witnessing where applicable, and confirmation that called-out NDE method and coverage were performed and reported. Performed against marked-up isometrics with TML / weld map references.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
