INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('e1a0772f-8315-40a3-b610-2a40c91ae7b6','post_tensioning_grouting_inspection','Post-Tensioning & Grouting Inspection (PTI M55)','1','Post-tensioning','global','12','220000','cci_advanced'::public.cci_credential_tier,'Inspection of post-tensioned concrete tendon stressing and duct grouting per PTI M55 / FHWA HIF-13-026. Includes duct alignment verification, jacking force / elongation log, grout-mix proportions, and grout-fill verification (vacuum or strand-integrity test). Inspector must hold PTI Level 2 Field Specialist certification.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('cc8286fb-a99f-41ee-9e12-a04602e98978','pre_startup_safety_review_mechanical_package','Pre-Startup Safety Review — Mechanical Package (OSHA PSM §1910.119(i))','1','PSSR','global','12','450000','cci_lead'::public.cci_credential_tier,'Lead-inspector facilitation of a Pre-Startup Safety Review on a new or significantly modified mechanical package per OSHA PSM 29 CFR 1910.119(i). Confirms construction is in accordance with design specs, safety / operating / maintenance procedures are in place, the Process Hazard Analysis recommendations are addressed, and training of affected personnel is complete. Output is the signed PSSR closure with action item list.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('432d9439-9c8e-46b0-aa26-cd90a804a653','process_safety_information_audit','Process Safety Information Audit (PSM §1910.119(d))','1','Process Safety Information','global','36','350000','cci_advanced'::public.cci_credential_tier,'Audit of the site Process Safety Information per OSHA PSM Element 3 (1910.119(d)). Covers chemicals (SDS, reactivity, corrosivity), technology (PFDs, max intended inventory, process chemistry), and equipment (P&IDs, material of construction, ventilation, safety system design basis, RAGAGEP compliance). Output is the PSI gap register and supports the broader PSM compliance audit.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('51339d1b-59c5-433f-9a75-5f1e04e33a5f','psm_compliance_audit_osha_1910_119','PSM Compliance Audit (OSHA 1910.119)','1','Process Safety Management','global','36','850000','cci_lead'::public.cci_credential_tier,'Full Process Safety Management compliance audit per OSHA 29 CFR 1910.119(o). Covers all 14 PSM elements: employee participation, process safety information, PHA, operating procedures, training, contractors, PSSR, mechanical integrity, hot-work permit, MOC, incident investigation, emergency planning, compliance audits, and trade secrets. OSHA 1910.119(o)(1) mandates compliance audits at least every 3 years; auditor must be a knowledgeable person.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('2d77fd7c-e4ef-4adc-ba05-75e8e269f7cd','psv_pop_test_campaign_api_576','PSV Pop-Test Campaign (API 576 / ASME PTC 25)','1','Pressure Relief Device Testing','global','60','420000','cci_advanced'::public.cci_credential_tier,'Multi-PSV pop-test campaign on pressure safety valves removed during turnaround. Performed at a certified VR-stamped repair shop or on-site test stand per ASME PTC 25. Covers visual condition, set-pressure verification, simmer, blowdown, seat tightness, and re-installation tagging. Output supports the site PSV inspection register and OSHA PSM MI requirement.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('3c8beb8d-3cbe-4847-ac17-f237eb98a153','pv_solar_string_acceptance_testing','PV Solar String Acceptance Testing (IEC 62446-1)','1','PV solar acceptance','global','12','240000','cci_advanced'::public.cci_credential_tier,'String-level acceptance testing of utility-scale or commercial PV arrays per IEC 62446-1 §6 (electrical tests). Covers continuity of protective conductors, polarity, open-circuit voltage and short-circuit current per string, insulation resistance to ground, and I-V curve traces on a representative sample. Output feeds the EPC commissioning package.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('91a3336f-088a-44fc-b170-e589325cfa30','rbi_walkdown_data_collection','RBI Walkdown + Data Collection (API 580/581)','1','Risk-based inspection','global','60','550000','cci_lead'::public.cci_credential_tier,'On-site data collection sprint supporting a Risk-Based Inspection assessment per API 580 methodology / API 581 implementation. Captures equipment list with damage mechanisms, corrosion-circuit walkdown, CML/TML population review, and consequence-of-failure interview with operations. Output feeds the RBI software model. Lead-level inspector with prior RBI team experience required.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('5944ce47-cb5a-4ad0-bc85-e51f880f575c','reactor_internals_post_turnaround_inspection','Reactor Internals Post-Turnaround Inspection','1','Reactor Internals','global','60','480000','cci_advanced'::public.cci_credential_tier,'Post-turnaround internal inspection of a fixed-bed or fluidised-bed reactor. Covers refractory condition (where present), internal grid / distributor / collector condition, scallop and centerpipe condition, gasket-seat surfaces, and confirmation of catalyst-bed levelness pre-loading. Includes confined-space entry coordination and inert-atmosphere oversight.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('4c3ab8ea-91eb-4ba8-acdb-577fa1c6ed2a','rotating_equipment_laser_alignment','Rotating Equipment Laser Shaft Alignment','1','Shaft alignment','global','12','90000','cci_basic'::public.cci_credential_tier,'Cold and hot shaft alignment of pump / motor, motor / gearbox / driven, or turbine / driven trains using a laser alignment system. Records pre-alignment as-found offsets and angles, soft-foot results, achieved as-left tolerances against vendor / API 686 acceptance, and growth compensation where supplied. Suitable for installation, post-overhaul, and post-shutdown realignment scopes.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('c1d9b24c-0227-4287-a864-9decfeced0d6','rt_radiography_pipeline_girth_welds','Radiography — Pipeline Girth Welds','1','NDT — Radiography','global','12','280000','cci_advanced'::public.cci_credential_tier,'Radiographic inspection of cross-country pipeline girth welds per API 1104 §11 (radiographic acceptance). Includes radiation safety survey, IQI sensitivity verification, image archival (film or CR/DR), and a radiographic interpretation report. Inspector must hold a current ASNT Level II RT certification.','t','industrial_ndt'::public.inspection_domain,'2026-05-28 16:15:23.17109+00','2026-05-28 16:15:23.17109+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('beb556f7-5190-44e2-82bf-dc4bc30dc276','shotcrete_application_aci_506','Shotcrete Application Inspection (ACI 506)','1','Shotcrete inspection','global','12','140000','cci_advanced'::public.cci_credential_tier,'Inspection of dry-mix or wet-mix shotcrete application per ACI 506R-16 and ACI 506.2. Verifies pre-construction nozzleman qualification (ACI CP-60 / ASA), surface preparation, nozzle distance and angle, layer thickness, rebound disposal, and curing. Required on tunnel, retaining-wall, and slope-stabilisation work.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('9d205ed9-c1e9-445d-848a-7c7603fa11ca','sis_proof_testing_iec_61511','Safety Instrumented System Proof Testing (IEC 61511 / ISA 84)','1','Safety Instrumented Systems','global','12','650000','cci_lead'::public.cci_credential_tier,'Proof testing of one or more Safety Instrumented Functions per IEC 61511-1 §16 (or ISA 84.00.01). Validates that each sensor → logic-solver → final-element loop meets its credited PFDavg and SIL claim. Records bypass authorisation, test procedure, results vs. acceptance criteria, fault-finding and corrective actions, and SIL re-verification calculations. Lead-level inspector with functional-safety certification (TÜV FSEng or equivalent) required.','t','chemical_process'::public.inspection_domain,'2026-05-28 17:02:47.823708+00','2026-05-28 17:02:47.823708+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('61b7a4d2-2773-48e1-96aa-334000b83393','structural_steel_coating_dft_audit','Structural Steel Coating DFT Audit (SSPC PA 2)','1','Structural coating audit','global','12','90000','cci_basic'::public.cci_credential_tier,'Dry-film thickness (DFT) and adhesion audit of protective coatings on structural steel per SSPC PA 2. Includes statistical DFT sampling per SSPC frequency tables, pull-off adhesion testing (ASTM D4541), environmental-conditions logging, and acceptance against the project paint specification.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('2a4b9df2-c20c-4089-942f-5779d485b630','structural_steel_high_strength_bolting','High-Strength Bolting Inspection (RCSC / AISC 348)','1','Bolting inspection','global','12','60000','cci_basic'::public.cci_credential_tier,'Inspection of slip-critical and pretensioned high-strength bolted connections per the RCSC Specification (referenced by AISC 348). Verifies bolt grade, lubrication, pre-installation verification, and the chosen installation method (turn-of-nut, calibrated wrench, twist-off, or direct-tension indicator).','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('a992c93f-f67f-444f-8cfe-4e223ab3ba42','structural_steel_visual_weld_aisc','Structural Steel Visual Weld Inspection (AISC 360 / AWS D1.1)','1','Structural steel welding inspection','global','12','180000','cci_advanced'::public.cci_credential_tier,'Visual weld inspection of structural-steel assemblies per AISC 360 Chapter N and AWS D1.1. Covers WPS / PQR verification, pre-, in-process, and post-weld visual acceptance, and connection sign-off. Inspector must hold a current AWS CWI or equivalent.','t','civil_construction'::public.inspection_domain,'2026-05-28 16:25:32.825436+00','2026-05-28 16:25:32.825436+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
