INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('bebfbc9f-66c0-422a-b188-63a4bde9d200','transformer_oil_sampling_dga','Transformer Oil Sampling — DGA (IEEE C57.104)','1','Transformer condition monitoring','global','12','80000','cci_basic'::public.cci_credential_tier,'On-site collection of oil samples from oil-immersed power transformers for laboratory Dissolved Gas Analysis (DGA) per IEEE C57.104. Includes sampling-valve cleaning, sample-bottle/syringe identification, chain-of-custody, and field interpretation of returned lab results against the Doernenburg / Rogers / IEC 60599 ratio methods.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('a289a24d-7f3a-4022-81b3-88b3e152e745','ups_battery_bank_acceptance','UPS + Battery Bank Acceptance Testing (IEEE 1188 / 450)','1','UPS & battery testing','global','12','100000','cci_basic'::public.cci_credential_tier,'Acceptance and condition testing of static UPS systems and their VRLA or vented lead-acid battery strings per IEEE 1188-2005 (VRLA) and IEEE 450-2020 (vented). Includes per-cell voltage and internal resistance / impedance readings, inter-cell connection torque verification, optional capacity discharge test, and a runtime transfer test on the UPS.','t','electrical'::public.inspection_domain,'2026-05-28 16:33:25.049893+00','2026-05-28 16:33:25.049893+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
INSERT INTO public.inspection_scope_templates (id,slug,name,version,category,region,validity_months,base_price_cents,requires_credential_tier,description_md,is_active,domain,created_at,updated_at) VALUES ('4606de81-f27b-45b3-9877-c0f71b5e4b22','vibration_baseline_acceptance_iso_20816','Commissioning Vibration Baseline (ISO 20816 / ISO 10816)','1','Vibration commissioning','global','12','140000','cci_advanced'::public.cci_credential_tier,'Commissioning-time vibration baseline measurement on newly installed rotating machinery per ISO 20816 series (and legacy ISO 10816). Captures overall velocity / displacement / acceleration per axis per bearing per running condition, plots against acceptance zones, and archives the FFT spectra as the run-in reference for future condition monitoring trending.','t','mechanical_field'::public.inspection_domain,'2026-05-28 16:51:50.765716+00','2026-05-28 16:51:50.765716+00') ON CONFLICT (id) DO UPDATE SET slug=EXCLUDED.slug,name=EXCLUDED.name,version=EXCLUDED.version,category=EXCLUDED.category,region=EXCLUDED.region,validity_months=EXCLUDED.validity_months,base_price_cents=EXCLUDED.base_price_cents,requires_credential_tier=EXCLUDED.requires_credential_tier,description_md=EXCLUDED.description_md,is_active=EXCLUDED.is_active,domain=EXCLUDED.domain,updated_at=EXCLUDED.updated_at;
